SELECT CASE WHEN s.rating >= 3.5 THEN 'high' WHEN s.rating >= 2.3 THEN 'mid' ELSE 'low' END AS rating_bucket, COUNT(*) AS total_count, SUM(p.price) AS total_price FROM products p LEFT JOIN suppliers s ON p.supplier_id = s.id WHERE s.rating BETWEEN 2.0 AND 3.1 GROUP BY CASE WHEN s.rating >= 3.5 THEN 'high' WHEN s.rating >= 2.3 THEN 'mid' ELSE 'low' END ORDER BY total_count DESC, total_price
